import{z as A,x as B,o as n,c as d,q as s,j as o,D as E,d as e,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"定点与浮点","description":"","frontmatter":{"title":"定点与浮点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fixed-and-float.md","filePath":"cs/fixed-and-float.md","lastUpdated":1791413859000}'),p={name:"cs/fixed-and-float.md"};function m(f,a,h,c,u,C){const r=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=s('<h1 id="定点与浮点" tabindex="-1">定点与浮点 <a class="header-anchor" href="#定点与浮点" aria-label="Permalink to &quot;定点与浮点&quot;">​</a></h1><div class="epigraph"><p>整数编码把小数点钉死在某一位；要同时覆盖很大和很小，必须让小数点跟着指数走。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Goldberg, What Every Computer Scientist Should Know About Floating-Point Arithmetic, 1991 整理</footer></div><p>上一课<a href="/cs/sign-magnitude">符号幅度与反码对照</a>钉死了有符号整数：同一套模 \\(2^n\\) 加法，溢出按同号和异号读。本课不重讲负权，也不从「实数是什么」另起。缺口是：补码只能表示整数。测量、比例、后课的地址偏移以外的「带小数的量」，还没有编码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 位补码的间距处处是 \\(1\\)。要把间距改成 \\(2^{-f}\\)，只需宣布小数点在第 \\(f\\) 位之后：这是<strong>定点</strong>。可表示集合仍是一个等差格子，动态范围仍约 \\(2^n\\)。科学计算要的是另一件事：相对精度大致均匀，绝对值可以从很小到很大。缺口因此不是再造一套补码，而是把一个数拆成<strong>尾数与指数</strong>，让格子在原点附近变密、在远处变疏。</p><p><span class="marginnote">数字实例：8 位补码宣布 \\(f=4\\) 就是 Q4.4 定点数：0110 1000 按整数读是 104，按定点读就是 \\(104/16 = 6.5\\)。可表示范围变成 \\(-8.0\\) 到约 \\(7.9375\\)，间距处处 \\(1/16\\)——范围与精度在选 \\(f\\) 那一刻就钉死了。</span></p><p>本课只钉这两种读法的差别，不把位域写成 IEEE 754 的具体宽度。那是<a href="/cs/ieee-754">下一课</a>的缺口。</p><h3 id="浮点不是「实数」" tabindex="-1">浮点不是「实数」 <a class="header-anchor" href="#浮点不是「实数」" aria-label="Permalink to &quot;浮点不是「实数」&quot;">​</a></h3><p>定点是缩放整数，加减可以先对齐小数点再走整数 ALU。浮点的加减必须先对阶：指数不同则尾数要移位。结果通常不能精确表示，只能舍入。把浮点当成「连续量终于回来了」，会把<a href="/cs/bit-as-distinction">第一课</a>的判决丢掉：浮点仍然是有限比特串。</p><p><span class="marginnote">Goldberg 强调：浮点是有限集合上的算术，不是 \\(\\mathbb{R}\\) 的子集运算。Patterson/Hennessy 先讲定点缩放，再引入 \\(x = \\pm m\\times b^e\\)。</span></p><p><span class="marginnote">直觉类比：定点像一把普通刻度尺，每格一样宽；浮点像一把对数刻度尺，靠零处刻度极密、大数处极疏。所以浮点能同时「量细菌」和「量星球」，代价是每一段的格子宽窄不一，小数的精度和大数的精度都要重新算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定点：选定 \\(f\\)，数值为 \\(\\mathrm{val}(x)\\cdot 2^{-f}\\)（补码或无符号皆可）。乘法是整数乘再算术移位；溢出仍按整数规则，只是单位改了。</p><p>浮点：约定符号、尾数 \\(m\\)、指数 \\(e\\)，数值 \\(\\pm m\\times 2^e\\)（基 \\(2\\) 是后课默认）。规格化要求 \\(m\\) 落在半开区间 \\([1,2)\\)，使同一值只有一种写法——本课只要求这个直觉，隐藏位与偏置指数留给 IEEE 754。</p>',14)),(n(),o(l,null,{default:E(()=>[i(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E8%A1%A5%E7%A0%81%E6%95%B4%E6%95%B0%22%5D%20--%3E%20FIX%5B%22%E5%AE%9A%E7%82%B9%EF%BC%9A%E9%92%89%E6%AD%BB%E5%B0%8F%E6%95%B0%E7%82%B9%22%5D%0A%20%20FIX%20--%3E%20FLT%5B%22%E6%B5%AE%E7%82%B9%EF%BC%9A%E6%8C%87%E6%95%B0%E7%A7%BB%E5%8A%A8%E5%B0%8F%E6%95%B0%E7%82%B9%22%5D%0A%20%20FLT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AIEEE%20754%20%E4%BD%8D%E5%9F%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("定点把精度预算花在绝对误差上，适合货币的最小单位、传感器的固定刻度。浮点把预算花在有效位数上：加减会吞掉阶差过大的尾数，这是"),t("strong",null,"精度损失"),e("，不是补码那种溢出旗标。两种失败模式不要混名。")],-1)),(n(),o(l,null,{default:E(()=>[i(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIX%5B%22%E5%AE%9A%E7%82%B9%3A%20%E5%B0%8F%E6%95%B0%E7%82%B9%E9%92%89%E5%9C%A8%E7%AC%AC%20f%20%E4%BD%8D%22%5D%20--%3E%20U%5B%22%E6%A0%BC%E5%AD%90%E5%9D%87%E5%8C%80%3A%20%E9%97%B4%E8%B7%9D%E5%A4%84%E5%A4%84%202%5E-f%22%5D%0A%20%20U%20--%3E%20A%5B%22%E5%A4%A7%E6%95%B0%E9%99%84%E8%BF%91%E4%B8%80%E6%A0%B7%E5%AF%86%3A%20%E5%8A%A8%E6%80%81%E8%8C%83%E5%9B%B4%E5%B0%8F%22%5D%0A%20%20FLT%5B%22%E6%B5%AE%E7%82%B9%3A%20%E6%8C%87%E6%95%B0%20e%20%E6%8C%AA%E5%8A%A8%E5%B0%8F%E6%95%B0%E7%82%B9%22%5D%20--%3E%20V%5B%22%E6%8C%87%E6%95%B0%E5%B0%8F%3A%20%E6%A0%BC%E5%AD%90%E5%AF%86%2C%20%E7%B2%BE%E7%BB%86%22%5D%0A%20%20FLT%20--%3E%20W%5B%22%E6%8C%87%E6%95%B0%E5%A4%A7%3A%20%E6%A0%BC%E5%AD%90%E7%96%8F%2C%20%E7%B2%97%E7%95%A5%22%5D%0A%20%20V%20--%3E%20R%5B%22%E7%9B%B8%E5%AF%B9%E7%B2%BE%E5%BA%A6%E5%A4%A7%E8%87%B4%E5%9D%87%E5%8C%80%22%5D%0A%20%20W%20--%3E%20R%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p>乘除对浮点相对自然：尾数乘、指数加。加减才是贵的。后课 ALU 会先做整数，浮点通路是另一套；本课只要求：同一比特串，读法从「整数」换成「定点或浮点」之后，相等关系都变了。</p><p><span class="marginnote">常见误区：初学者以为浮点加减「只是多处理一次小数点」。实际要先对阶：把指数小的尾数右移到指数对齐，类似 \\(2^{30} + 1\\) 的运算里那个 1 会在移位中被整个丢掉——这是精度损失，不会像补码溢出那样置旗标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定 <code>binary32</code> 的 8 位指数、23 位尾数，不引入 NaN、无穷、非规格化数。也不讨论十进制浮点或区间算术。字符、文本编码与数值无关，是再后一课。</p><p>后课默认：谈到「机器上的非整数」，先问是定点缩放还是浮点。浮点的可移植位型，下一课才钉死。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定点是缩放整数，格子均匀；浮点用指数换动态范围。</li><li>浮点加减要对阶并舍入；失败是精度损失，不是补码溢出。</li><li>规格化使同一值尽量一种写法；具体位域是后课。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；Goldberg, 1991。</li></ul>',7))])}const F=A(p,[["render",m]]);export{b as __pageData,F as default};
